fn transpose(arr: Vec<Vec<i8>>) -> Vec<Vec<i8>> {
    // If the input is empty (though by problem statement it shouldn't be),
    // just return an empty vector.
    if arr.is_empty() {
        return Vec::new();
    }
    let rows = arr.len();
    let cols = arr[0].len();

    // Initialize the result with `cols` rows, each of length `rows`.
    let mut result = vec![vec![0i8; rows]; cols];

    for i in 0..rows {
        for j in 0..cols {
            // Place element (i,j) of the original at (j,i) in the result.
            result[j][i] = arr[i][j];
        }
    }

    result
}

